
let headerSubMenu = document.querySelectorAll('.js-header-menu .header-menu-item.has-submenu');
if(headerSubMenu){
	let menuHoverTimeout;
	headerSubMenu.forEach(function (menuItem){
		if (window.matchMedia('(min-width: 768px)').matches) {
			if(window.matchMedia('(hover:hover)').matches){
				menuItem.addEventListener('mouseenter', function () {
					let itemContentBlock = this.querySelector('.header-menu-item-submenu');
					let itemCurrencyMenu = this.querySelector('.header-submenu-currency-form');
					let itemContentBlockHeight = 324;
					if (this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu')) {
						this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu').removeAttribute('style')
					}
					if (this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu')) {
						this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu').classList.remove('open-submenu');
					}

					if (itemContentBlock) {
						itemContentBlockHeight = itemContentBlock.scrollHeight;
						itemContentBlock.style.height = itemContentBlockHeight + 'px';
					}
					if(itemCurrencyMenu && window.matchMedia('(min-width: 1025px)').matches){
						itemCurrencyMenu.style.marginLeft = this.getBoundingClientRect().left - 20 + 'px'
					}
					clearTimeout(menuHoverTimeout);

					this.classList.add('open-submenu');

					if(document.querySelector('#header-search')){
						document.querySelector('#header-search').style.height = 0;
						document.querySelector('#header-search').classList.remove('open');
						document.body.classList.remove('disable-scroll');
					}
					if(document.querySelector('.header-search-overflow')){
						document.querySelector('.header-search-overflow').classList.remove('open');
					}

				});
				menuItem.addEventListener('mouseleave', function () {
					let _this = this;
					menuHoverTimeout = setTimeout(function () {
						if(_this.querySelector('.header-menu-item-submenu ')){
							_this.querySelector('.header-menu-item-submenu ').style.height = 0;
						}
						_this.classList.remove('open-submenu');
					}, 200);
				});
			}else{
				menuItem.addEventListener('click', function (e) {
					if(!e.target.closest('.header-submenu-inner')) {
						e.preventDefault();
						let itemContentBlock = this.querySelector('.header-menu-item-submenu');
						let itemCurrencyMenu = this.querySelector('.header-submenu-currency-form');
						let itemContentBlockHeight = 324;
						if (this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu')) {
							this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu').removeAttribute('style')
						}
						if (this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu')) {
							this.closest('.header').querySelector('.header-menu-item.has-submenu.open-submenu').classList.remove('open-submenu');
						}

						if (itemContentBlock) {
							itemContentBlockHeight = itemContentBlock.scrollHeight;
							itemContentBlock.style.height = itemContentBlockHeight + 'px';
						}
						if (itemCurrencyMenu && window.matchMedia('(min-width: 1025px)').matches) {
							itemCurrencyMenu.style.marginLeft = this.getBoundingClientRect().left - 20 + 'px'
						}
						this.classList.add('open-submenu');

						if (document.querySelector('#header-search')) {
							document.querySelector('#header-search').style.height = 0;
							document.querySelector('#header-search').classList.remove('open');
							document.body.classList.remove('disable-scroll');
						}
						if (document.querySelector('.header-search-overflow')) {
							document.querySelector('.header-search-overflow').classList.remove('open');
						}
					}
				});
			}
		}
	})
}
let mobileMenuButton = document.querySelector('.js-header-menu-button');
if(mobileMenuButton){
	mobileMenuButton.addEventListener('click',function (){
		let altText = this.dataset.altText;
		if(this.querySelector('span:not(.icon)')){
			this.setAttribute('data-alt-text', this.querySelector('span:not(.icon)').innerHTML);
			this.querySelector('span:not(.icon)').innerHTML = altText;
		}
		if(this.classList.contains('open')){
			if(this.querySelector('span.icon')){
				this.querySelector('span.icon').classList.remove('icon-minus');
				this.querySelector('span.icon').classList.add('icon-plus');
			}

			if(document.querySelector('#header-mobile-menu')){
				document.querySelector('#header-mobile-menu').classList.remove('open');
				document.body.classList.remove('disable-scroll');
			}
			if(document.querySelector('.js-header-menu-overflow')){
				document.querySelector('.js-header-menu-overflow').classList.remove('open');
			}
			this.classList.remove('open')
		}else{
			if(this.querySelector('span.icon')){
				this.querySelector('span.icon').classList.remove('icon-plus');
				this.querySelector('span.icon').classList.add('icon-minus');
			}

			if(document.querySelector('#header-mobile-menu')){
				document.querySelector('#header-mobile-menu').classList.add('open');
				document.body.classList.add('disable-scroll');
			}
			if(document.querySelector('.js-header-menu-overflow')){
				document.querySelector('.js-header-menu-overflow').classList.add('open');
			}
			this.classList.add('open');
		}
	})
}
