document.body.addEventListener("click", function (event) {
	if(!window.matchMedia('(hover:hover)').matches) {
		if (!event.target.classList.contains("header-menu-item") && event.target.closest(".header-menu-item.has-submenu") == undefined) {
			if(document.querySelector('.header')){
				if (document.querySelector('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu')) {
					document.querySelector('.header').querySelector('.header-menu-item.has-submenu.open-submenu .header-menu-item-submenu').removeAttribute('style');
				}
				if (document.querySelector('.header').querySelector('.header-menu-item.has-submenu.open-submenu')) {
					document.querySelector('.header').querySelector('.header-menu-item.has-submenu.open-submenu').classList.remove('open-submenu');
				}
			}
		}
	}
	if ((event.target.classList.contains("collapsible-button") && event.target.closest('.js-collapsible-wrapper')) || (event.target.closest(".collapsible-button") && event.target.closest('.js-collapsible-wrapper'))) {
		event.preventDefault();
		if (event.target.closest('.collapsible-block')) {
			if (event.target.closest('.collapsible-block').classList.contains('open')) {
				event.target.closest('.collapsible-block').classList.remove('open');
				if (event.target.closest('.collapsible-block').querySelector('.collapsible-content')) {
					event.target.closest('.collapsible-block').querySelector('.collapsible-content').style.height = 0;
				}
			} else {
				event.target.closest('.collapsible-block').classList.add('open');
				if (event.target.closest('.collapsible-block').querySelector('.collapsible-content')) {
					event.target.closest('.collapsible-block').querySelector('.collapsible-content').style.height = event.target.closest('.collapsible-block').querySelector('.collapsible-content').scrollHeight + 20 + 'px';
				}
			}
		}
	}

	if (!event.target.closest('.js-filter-dropdown')) {
		if(document.querySelectorAll('.js-filter-dropdown')){
			document.querySelectorAll('.js-filter-dropdown').forEach(function (dropdown){
				if(dropdown.querySelector('.collection-filter-dropdown-list')){
					dropdown.querySelector('.collection-filter-dropdown-list').classList.remove('open')
				}
			})
		}
	}
});

