function quantity() {
	let quantityButtons = document.querySelectorAll('.js-quantity-button');
	if(quantityButtons){
		quantityButtons.forEach(function (button){
			button.addEventListener('click',function (){
				let oldValue = '';
				let newValue = 0;
				let quantityInput = '';
				let quantityBlock = this.closest('.js-quantity');
				if(quantityBlock){
					quantityInput = quantityBlock.querySelector('.js-quantity-input');
					if(quantityInput){
						oldValue = parseInt(quantityInput.value);
						if(this.classList.contains('quantity-button-increase')){
							newValue = oldValue + 1;
						}else{
							if (oldValue > 0) {
								newValue = oldValue - 1;
							} else {
								newValue = 0;
							}
						}
						quantityInput.value = newValue;
						quantityInput.dispatchEvent(new Event('change'));
					}
				}

			})
		})
	}
}

