function galleryMarquee(selector) {
	const parentSelector = document.querySelector(selector);
	const firstElement = parentSelector.children[0];
	const lastElement = parentSelector.children[1];
	if(lastElement){
		lastElement.remove();
	}
	if(firstElement){
		const parentSelectorWidth = firstElement.getBoundingClientRect().width;
		const firstElementWidth = firstElement.getBoundingClientRect().width;
		firstElement.style.minWidth = firstElement.scrollWidth+'px';
		firstElement.style.setProperty('--gallery-width',`-${firstElement.scrollWidth + 40}px`);
		const clone = parentSelector.innerHTML;
		let i = 0;
		parentSelector.insertAdjacentHTML('beforeend', clone);
	}
}

