let uploadedFiles = [];

const validationFiles = (files) => {
    const validatedFiles = []
    const extensions = ['jpeg', 'jpg', 'png', 'JPEG', 'JPG', 'PNG']

	files.forEach(file => {
		const extension = file.name.split('.').pop()
        const size = (file.size / (1000 * 1000)).toFixed(2)

		if (extensions.indexOf(extension) !== -1) validatedFiles.push(file)
	})

	return validatedFiles
}

const uploadFiles = (upload, files) => {
    const validatedFiles = validationFiles([...files]);

    validatedFiles.forEach(file => {
        uploadFile(upload, file)
    });

	updateUploaderView();
}

const updateUploaderView = () => {
    const listLabel = document.querySelectorAll('.form-uploader-label .form-uploader-file-placeholeder');
	const itemsToShow = 3 - uploadedFiles.length;

	listLabel.forEach((item, index) => {
		const show = index < itemsToShow;

		listLabel[index].style.display = show ? 'block' : 'none';
	})

	document.querySelector('.form-uploader-info .info').style.display = uploadedFiles.length == 3 ? 'none' : 'block';
}

const uploadFile = async (upload, file) => {
    const list = upload.querySelector('.form-uploader-files')
	const input = upload.querySelector('input[type="file"]')

    const el = document.createElement('div')
    const elImage = document.createElement('div')
    const elImageFile = document.createElement('img')
    const elRemove = document.createElement('div')
	const elRemoveSpan = document.createElement('span')


    el.classList.add('file')
    elImage.classList.add('file-image')
    elImageFile.src = URL.createObjectURL(file)
    elRemove.classList.add('file-remove')

	elRemove.appendChild(elRemoveSpan)
    el.appendChild(elRemove)
    list.prepend(el)
    el.appendChild(elImage)
    elImage.appendChild(elImageFile);

	uploadedFiles.push({
		file,
		id: file.lastModified,
	});

	input.value ='';
	
    elRemove.addEventListener('click', () => {
        el.remove()

		const indexToRemove = uploadedFiles.findIndex((item) => item.id === file.lastModified);
		uploadedFiles.splice(indexToRemove, 1)

		updateUploaderView();
	})

	document.querySelector('.js-clear-form').addEventListener('click', function () {
		document.querySelectorAll('.form-uploader-files .file')?.forEach ((itemFile) => {
			itemFile.remove()
		})

		uploadedFiles = []

		document.querySelectorAll('.form-uploader-label .form-uploader-file-placeholeder')?.forEach ((itemPlaceholder) => {
			itemPlaceholder.style.display = 'block'
		})
	})
}

const initUploads = () => {
    const uploads = document.querySelectorAll('.form-uploader')
    const events = ['dragenter', 'dragover', 'dragleave', 'drop']

    uploads && uploads.length && uploads.forEach((upload) => {
        const input = upload.querySelector('input[type="file"]')

        events.forEach(event => {
            upload.addEventListener(event, (e) => {
                e.preventDefault()
                e.stopPropagation()
            })
        })

        upload.addEventListener('drop', (e) => {        
            uploadFiles(upload, e.dataTransfer.files)
        })

        input.addEventListener('change', (e) => {
            uploadFiles(upload, input.files)
        }, { passive: true })
    })
}

initUploads()

