function mouseMove(e, block) {
	let image = block.querySelector('img');
	let blockWidth = block.offsetWidth
	let blockHeight = block.offsetHeight;
	let imageHeight = image.clientHeight*3;
	let imageWidth = image.clientWidth*3;

	let x = e.layerX;
	let y = e.layerY;

	let imageTransformX = -1 * (x / blockWidth) * (imageWidth - blockWidth);
	let imageTransformY = -1 * (y / blockHeight) * (imageHeight - blockHeight);


	if(block.classList.contains('zoomed')){
		image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`);
	}
}

function toucheMove(e,block) {
	if(block.classList.contains('zoomed')){
		e.preventDefault();

		let image = block.querySelector('img');
		let blockWidth = block.offsetWidth
		let blockHeight = block.offsetHeight;
		let imageHeight = image.clientHeight*3;
		let imageWidth = image.clientWidth*3;

		let x = e.touches[0].clientX;
		let y = e.touches[0].clientY;


		let tranclateX = parseInt(new WebKitCSSMatrix(window.getComputedStyle(image).transform).m41)
		let tranclateY = parseInt(new WebKitCSSMatrix(window.getComputedStyle(image).transform).m42)

		let imageTransformX ;
		let imageTransformY ;



		if(previousX > x){
			imageTransformX = tranclateX - (previousX - x);
		}else if(previousX< x){
			imageTransformX = tranclateX + Math.abs(previousX - x);
		}
		if(previousY > y){
			imageTransformY = tranclateY - (previousY - y);
		}else if(previousY< y){
			imageTransformY = tranclateY + Math.abs(previousY - y);
		}


		if(imageTransformX >= 0){
			imageTransformX = 0
		}
		if(imageTransformX < (-1* (imageWidth - blockWidth))){
			imageTransformX = (-1* (imageWidth - blockWidth))
		}
		if(imageTransformY > 0){
			imageTransformY = 0
		}
		if(imageTransformY < (-1* (imageHeight - blockHeight))){
			imageTransformY = (-1* (imageHeight - blockHeight))
		}

		if(imageTransformX != null && imageTransformY != null){
			image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`)
		}
		previousX = x;
		previousY = y;
	}
}

function starterPosition(e, block){
	let image = block.querySelector('img');
	let blockWidth = block.offsetWidth
	let blockHeight = block.offsetHeight;
	let imageHeight = image.clientHeight*3;
	let imageWidth = image.clientWidth*3;

	let x = e.layerX;
	let y = e.layerY;
	if (isTouchDevice()) {
		 x = e.clientX;
		 y = e.clientY;
	}

	let imageTransformX = -1 * (x / blockWidth) * (imageWidth - blockWidth);
	let imageTransformY = -1 * (y / blockHeight) * (imageHeight - blockHeight);

	image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px) scale(3)`);
	// setTimeout(function (){
	// 	image.setAttribute('style', `transform: translate(${imageTransformX}px,${imageTransformY}px)`);
	// },600)

}
function isTouchDevice() {
	return (('ontouchstart' in window) || (navigator.maxTouchPoints > 0) || (navigator.msMaxTouchPoints > 0));
}

